const API = "http://localhost:8000/api/v1";
type SetupState = "loading" | "required" | "complete" | "error";
type ChatMessage = { id?: string; role: string; content: string; status?: string };
type ModelRecord = { id: string; model: string; name: string; provider: string; status: string; metadata: { size_bytes?: number } };
