  const [conversations, setConversations] = useState<ConversationRecord[]>([]); const [conversationId, setConversationId] = useState(""); const [messages, setMessages] = useState<ChatMessage[]>([]); const [prompt, setPrompt] = useState(""); const [isStreaming, setIsStreaming] = useState(false); const [streamingMessageId, setStreamingMessageId] = useState("");
