  const [plugins, setPlugins] = useState<PluginRecord[]>([]); const [pluginName, setPluginName] = useState(""); const [pluginVersion, setPluginVersion] = useState("0.1.0"); const [pluginDescription, setPluginDescription] = useState("");
  const [instagramAccounts, setInstagramAccounts] = useState<InstagramAccountRecord[]>([]); const [instagramPublications, setInstagramPublications] = useState<InstagramPublicationRecord[]>([]); const [instagramAccountId, setInstagramAccountId] = useState(""); const [instagramEditingId, setInstagramEditingId] = useState(""); const [instagramLabel, setInstagramLabel] = useState(""); const [instagramAppId, setInstagramAppId] = useState(""); const [instagramAppSecret, setInstagramAppSecret] = useState(""); const [instagramUserId, setInstagramUserId] = useState(""); const [instagramToken, setInstagramToken] = useState(""); const [instagramApiVersion, setInstagramApiVersion] = useState("v26.0"); const [instagramEnabled, setInstagramEnabled] = useState(true); const [instagramAutoPublish, setInstagramAutoPublish] = useState(false); const [instagramPlacement, setInstagramPlacement] = useState<"feed" | "story">("feed"); const [instagramImageUrl, setInstagramImageUrl] = useState(""); const [instagramCaption, setInstagramCaption] = useState(""); const [instagramProfile, setInstagramProfile] = useState<InstagramAccountRecord["last_connection_profile"]>();
  const [facebookAccounts, setFacebookAccounts] = useState<FacebookAccountRecord[]>([]); const [facebookPublications, setFacebookPublications] = useState<FacebookPublicationRecord[]>([]); const [facebookAccountId, setFacebookAccountId] = useState(""); const [facebookEditingId, setFacebookEditingId] = useState(""); const [facebookLabel, setFacebookLabel] = useState(""); const [facebookAppId, setFacebookAppId] = useState(""); const [facebookAppSecret, setFacebookAppSecret] = useState(""); const [facebookPageId, setFacebookPageId] = useState(""); const [facebookToken, setFacebookToken] = useState(""); const [facebookApiVersion, setFacebookApiVersion] = useState("v26.0"); const [facebookEnabled, setFacebookEnabled] = useState(true); const [facebookAutoPublish, setFacebookAutoPublish] = useState(false); const [facebookPlacement, setFacebookPlacement] = useState<"feed" | "story">("feed"); const [facebookImageUrl, setFacebookImageUrl] = useState(""); const [facebookCaption, setFacebookCaption] = useState(""); const [facebookProfile, setFacebookProfile] = useState<FacebookAccountRecord["last_connection_profile"]>();
