  const auth = { Authorization: `Bearer ${token}` };

  useEffect(() => { fetch(`${API}/setup/status`).then(async response => { if (!response.ok) throw new Error(); setState((await response.json() as { setup_required: boolean }).setup_required ? "required" : "complete"); }).catch(() => { setState("error"); setNotice("No se pudo conectar con el Core."); }); }, []);
