  async function loadCatalog(accessToken = token): Promise<void> { const headers = { Authorization: `Bearer ${accessToken}` }; await fetch(`${API}/models/sync`, { method: "POST", headers }); const response = await fetch(`${API}/models`, { headers }); if (response.ok) setCatalog((await response.json() as { items: ModelRecord[] }).items); }
  async function initialize(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); const response = await fetch(`${API}/setup/initialize`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email, display_name: name, password }) }); if (!response.ok) return setNotice("No se pudo crear el administrador."); setState("complete"); setPassword(""); }
  async function login(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); const response = await fetch(`${API}/auth/login`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ email, password }) }); if (!response.ok) return setNotice("Credenciales inválidas."); const accessToken = (await response.json() as { access_token: string }).access_token; setToken(accessToken); setPassword(""); const headers = { Authorization: `Bearer ${accessToken}` }; const providers = await fetch(`${API}/providers/ollama/models`, { headers }); if (providers.ok) { const items = (await providers.json() as { items: { external_id: string; capabilities: string[] }[] }).items; const available = items.filter(item => item.capabilities.includes("completion")).map(item => item.external_id); setModels(available); setModel(available[0] ?? ""); } const history = await fetch(`${API}/conversations`, { headers }); if (history.ok) setConversations((await history.json() as { items: ConversationRecord[] }).items); await loadCatalog(accessToken); }
  async function openConversation(id: string): Promise<void> { const response = await fetch(`${API}/conversations/${id}/messages`, { headers: auth }); if (!response.ok) return; setConversationId(id); setMessages((await response.json() as { items: ChatMessage[] }).items); const record = conversations.find(item => item.id === id); if (record) setModel(record.model); }
  async function sendPrompt(text: string): Promise<void> { if (!text || !model || isStreaming) return; const headers = { "Content-Type": "application/json", ...auth }; let id = conversationId; if (!id) { const response = await fetch(`${API}/conversations`, { method: "POST", headers, body: JSON.stringify({ model }) }); if (!response.ok) return setNotice("No se pudo crear la conversación."); id = (await response.json() as { id: string }).id; setConversationId(id); setConversations(current => [{ id, title: "Nueva conversación", model }, ...current]); } setStreamingMessageId(""); setMessages(current => [...current, { role: "user", content: text }, { role: "assistant", content: "", status: "streaming" }]); const controller = new AbortController(); streamController.current = controller; setIsStreaming(true); try { const response = await fetch(`${API}/conversations/${id}/messages`, { method: "POST", headers, body: JSON.stringify({ content: text }), signal: controller.signal }); if (!response.ok || !response.body) throw new Error(); const reader = response.body.getReader(); const decoder = new TextDecoder(); let buffer = ""; while (true) { const chunk = await reader.read(); if (chunk.done) break; buffer += decoder.decode(chunk.value, { stream: true }); const frames = buffer.split("\n\n"); buffer = frames.pop() ?? ""; for (const frame of frames) { const data = frame.split("\n").find(line => line.startsWith("data: ")); if (!data) continue; if (frame.startsWith("event: message.started")) { const messageId = (JSON.parse(data.slice(6)) as { message_id: string }).message_id; setStreamingMessageId(messageId); setMessages(current => { const copy = [...current]; copy[copy.length - 1] = { ...copy[copy.length - 1], id: messageId }; return copy; }); } else if (frame.startsWith("event: message.delta")) { const delta = (JSON.parse(data.slice(6)) as { delta: string }).delta; setMessages(current => { const copy = [...current]; copy[copy.length - 1] = { ...copy[copy.length - 1], content: copy[copy.length - 1].content + delta }; return copy; }); } } } } catch (error) { if (!(error instanceof DOMException && error.name === "AbortError")) setNotice("La respuesta se interrumpió antes de completarse."); } finally { streamController.current = null; setStreamingMessageId(""); setIsStreaming(false); } }
  async function send(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); const text = prompt; setPrompt(""); await sendPrompt(text); }
  async function regenerate(index: number): Promise<void> { const previous = [...messages.slice(0, index)].reverse().find(item => item.role === "user"); if (previous) await sendPrompt(previous.content); }
  async function cancelStreaming(): Promise<void> { if (conversationId && streamingMessageId) await fetch(`${API}/conversations/${conversationId}/messages/${streamingMessageId}/cancel`, { method: "POST", headers: auth }); streamController.current?.abort(); }
