  async function openWorkflow(id: string): Promise<void> { const response = await fetch(`${API}/workflows/${id}`, { headers: auth }); if (!response.ok) return setNotice("No se pudo abrir el workflow."); const detail = await response.json() as WorkflowDetail; setWorkflowDetail(detail); const version = detail.versions[0]; if (version) { setWorkflowVersionId(version.id); setWorkflowGraph(JSON.stringify(version.graph, null, 2)); } }
  async function saveWorkflow(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); if (!workflowDetail) return; let graph: object; try { graph = JSON.parse(workflowGraph) as object; } catch { return setNotice("El grafo debe ser JSON válido."); } const response = await fetch(`${API}/workflows/${workflowDetail.id}/versions`, { method: "POST", headers: { "Content-Type": "application/json", ...auth }, body: JSON.stringify({ name: workflowDetail.name, description: workflowDetail.description, graph }) }); if (!response.ok) return setNotice("No se pudo guardar la versión."); await openWorkflow(workflowDetail.id); await loadWorkflows(); }
