  function editInstagramAccount(account: InstagramAccountRecord): void { setInstagramEditingId(account.id); setInstagramLabel(account.account_label); setInstagramAppId(account.app_id); setInstagramUserId(account.instagram_user_id); setInstagramApiVersion(account.api_version); setInstagramEnabled(account.enabled); setInstagramAutoPublish(account.auto_publish); setInstagramAppSecret(""); setInstagramToken(""); }
  async function saveInstagramAccount(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); setNotice(""); const body: Record<string, unknown> = { account_label: instagramLabel, app_id: instagramAppId, instagram_user_id: instagramUserId, api_version: instagramApiVersion, enabled: instagramEnabled, auto_publish: instagramAutoPublish }; if (instagramAppSecret) body.app_secret = instagramAppSecret; if (instagramToken) body.access_token = instagramToken; const response = await fetch(`${API}/plugins/instagram/accounts${instagramEditingId ? `/${instagramEditingId}` : ""}`, { method: instagramEditingId ? "PATCH" : "POST", headers: { "Content-Type": "application/json; charset=utf-8", ...auth }, body: JSON.stringify(body) }); if (!response.ok) return setNotice(await instagramError(response)); const saved = await response.json() as InstagramAccountRecord; setInstagramAppSecret(""); setInstagramToken(""); setInstagramEditingId(""); setInstagramAccountId(saved.id); setNotice("Cuenta guardada. Los secretos quedaron cifrados y ya no se muestran."); await loadInstagramAccounts(); }
  async function testInstagramConnection(): Promise<void> { if (!instagramAccountId) return setNotice("Seleccioná una cuenta de Instagram."); setNotice("Probando conexión…"); const response = await fetch(`${API}/plugins/instagram/test-connection`, { method: "POST", headers: { "Content-Type": "application/json", ...auth }, body: JSON.stringify({ account_id: instagramAccountId }) }); if (!response.ok) return setNotice(await instagramError(response)); const profile = await response.json() as InstagramAccountRecord["last_connection_profile"]; setInstagramProfile(profile); setNotice("Conexión verificada correctamente."); await loadInstagramAccounts(); }
  async function createInstagramContainer(event: FormEvent<HTMLFormElement>): Promise<void> { event.preventDefault(); if (!instagramAccountId) return setNotice("Seleccioná una cuenta de Instagram."); setNotice("Creando tarea durable…"); const response = await fetch(`${API}/plugins/instagram/media/image`, { method: "POST", headers: { "Content-Type": "application/json; charset=utf-8", ...auth }, body: JSON.stringify({ account_id: instagramAccountId, image_url: instagramImageUrl, caption: instagramCaption, placement: instagramPlacement }) }); if (!response.ok) return setNotice(await instagramError(response)); setInstagramImageUrl(""); setInstagramCaption(""); const selected = instagramAccounts.find(item => item.id === instagramAccountId); setNotice(selected?.auto_publish ? "Contenido en cola; se publicará automáticamente cuando esté listo." : "Contenedor en cola; quedará listo para tu confirmación."); await loadInstagramHistory(); }
  async function publishInstagramContainer(containerId: string): Promise<void> { if (!window.confirm("¿Confirmás la publicación real de este contenido en Instagram?")) return; const response = await fetch(`${API}/plugins/instagram/media/${containerId}/publish`, { method: "POST", headers: { "Content-Type": "application/json", ...auth }, body: JSON.stringify({ confirmed: true }) }); if (!response.ok) return setNotice(await instagramError(response)); setNotice("Publicación confirmada y enviada al worker."); await loadInstagramHistory(); }
  async function facebookError(response: Response): Promise<string> { try { const body = await response.json() as { detail?: string; error?: { message?: string } }; return body.detail ?? body.error?.message ?? `Facebook respondió con estado ${response.status}.`; } catch { return `Facebook respondió con estado ${response.status}.`; } }
